export const meta = {
  name: 'vg-sigma-tool',
  description: 'Build, independently check and fix a report-only V-G by episode step and tail sigma tool for the running phase screen (outcome-blind)',
  phases: [
    { title: 'Build', detail: 'builder writes SPEC, tool, tests, validations' },
    { title: 'Check', detail: 'independent re-implementation and mutation checks' },
    { title: 'Fix', detail: 'fix findings, re-validate (only if needed)' },
    { title: 'Recheck', detail: 'independent re-check of the fixed tool (only if a blocking finding was fixed)' },
  ],
}

const S2 = '/tmp/claude-0/-home-user-mesozoic-labs/184ee67c-2802-5235-8e52-6dc7daa72cd3/scratchpad'
const PS = '/home/user/work/phase_screen'
const VG = '/home/user/work/vg_tool'
const PY = S2 + '/venv/bin/python -I -B'

const RULES = `
HARD RULES (all agents):
- The phase screen PS (${PS}) is RUNNING right now and is OUTCOME-BLIND. Never open, read, list the contents of, hash, or stat-for-content anything under ${PS}/runs, ${PS}/reads, ${PS}/score, ${PS}/lost.json, ${PS}/tmp, or the continuation logs in ${PS}/logs. You MAY read (read only) ${PS}/criteria.txt, ${PS}/SCREEN.json, ${PS}/APPROVED, ${PS}/NOTES.txt, ${PS}/tools/** (the pinned harness code), ${PS}/validate/** (pre-launch validation outputs; outcome-free) and ${PS}/criteria_work/**. Never write anything in ${PS} (it is pinned; files are 0444 and must stay byte-identical).
- Write ONLY under your own folder inside ${VG} (set TMPDIR and MPLCONFIGDIR inside it). Never write in ${S2}, the git repo /home/user/mesozoic-labs, /tmp outside your folder, or anywhere else. Never redirect output to any path outside your folder. Never reference the null device (/dev/null) in any form, not even as a redirect target.
- No training, no optimizer step, no git or network writes.
- The CPU is shared with the 4 running screen continuations (4 cores). Run every validation with nice -n 19, one heavy process at a time, and keep validations small (a few episodes per pair). Measure the per-episode cost.
- Python: ${PY} (read-only venv). If a permission check refuses an action, stop and report it; do not work around it.
- Label every claim [measured] or [inferred]. Keep a command log with date -u timestamps in your folder.
`

const CONTEXT = `
CONTEXT
- PS is a pinned, approved CPU screen (report only): 8 PPO (MirrorKLPPO) continuations of the T. rex r10 stance policy from seed 42's checkpoint at 2,097,152 to E = 3,538,944: 4 control and 4 critic_phase, paired seeds 2901, 2911, 2921, 2931. In critic_phase ONLY the critic (value net) sees the episode phase: three features written into the always-zero command observation slots 60-62 (ramp = min(k,200)/200, settled = 1[k>=200], discount = 0.98^max(0,200-k)), k = the env's own _step_count at the observation (0 at reset). The actor's slots are forced to 0, the critic's phase columns were zeroed at load, VecNormalize stats on 60-62 frozen at mean 0 / var 1. Four stance reward terms pay only for k >= 200 (the hidden step gate the critic otherwise reads from the creeping tail angle). Details: ${PS}/criteria.txt (sections WHAT IS TRAINED, THE MANIPULATION CHECK), ${PS}/NOTES.txt, ${PS}/tools/bs_hooks.py, read_bs.py, bs_common.py, run_bs.py.
- The maintainer approved a SEPARATE report-only tool (never a line or secondary; it never changes the screen's reading), built while the screen runs and pinned by sha256 in the run log before the reading, to measure on each COUNTED continuation's final pair after the screen is scored:
  (1) the critic's error V - G by episode-step bucket [0,50), [50,150), [150,200), [200,250), [250,1000], per run and per arm (PR #655's Open Question 1; the PR-655 review asked for exactly these buckets), and
  (2) the tail's exploration noise: sigma = exp(log_std) (with any sigma floor the policy applies) for the tail_3 and tail_2 actuators, at S and at each saved pair and the final.
- Prior art to reuse and check against: the no-training why-probe ${S2}/com_revisit/notes/phase_probe (PREREG.txt, NOTES.txt, analysis*.txt and its scripts) and its verifier ${S2}/com_revisit/notes/verify_why, which compared the critic's V with realised returns by phase on s42. The finished critic-blind screen BS2 (${S2}/r10round/bias_screen2: criteria.txt, tools/, runs/*/01_stance/models/stage1_final.zip and the matching VecNormalize files) is complete and its outcomes are already known, so its pairs are fair game for validation.
`

const BUILD = `You are the BUILDER of a report-only measurement tool. ${CONTEXT}
${RULES}
TASK (your folder: ${VG}; create it):
1. Read the sources above (read only). Work out from the PS tool CODE (not from ${PS}/runs) exactly where each continuation saves its final pair (zip + VecNormalize) and saved pairs, how read_bs.py loads a pair, builds the training-config env, feeds the phase to the critic for critic_phase (critic form "phase+raw+settled") and evaluates values. Reuse those functions by importing PS's tools read only (sys.path insertion; -B so no pycache is written); do not copy-modify the arm logic.
2. Write ${VG}/SPEC.txt, a short pre-registration: inputs (each COUNTED continuation's final pair at E per the screen's score.json, plus the shared start pair at S as reference; sigma also at each saved pair); episodes per pair N (justify; e.g. 16-32) with NEW env seeds checked for collisions against every seed set named in ${PS}/criteria.txt, ${S2}/r10round/bias_screen2/criteria.txt, ${S2}/r10round/long_blind (criteria drafts/tools), the why-probe and the validations (write the check's output); on-policy stochastic actions (as in training) with fixed seeds; G = realised discounted return-to-go in the critic's own units (the training gamma; the training VecNormalize reward normalisation with frozen statistics, exactly as the buffer's returns are formed in training; a time-limit truncation at k = 1000 bootstrapped with V of the terminal observation as SB3 does; a true termination not bootstrapped); V from the arm's own critic form with the phase fed exactly as in training for critic_phase; buckets by k of the observation; statistics reported (per run per bucket: mean V-G, mean |V-G|, SE across episodes, counts; per arm medians; the control-minus-phase difference per bucket); the stated expectations (inferred): phase arm's V-G nearer 0 than control's in the 150-200 and 200-250 buckets; and an explicit statement that this is report only, outside the screen's reading, never a line or secondary. State the tail_3 and tail_2 action indices you use and how you verified them.
3. Write the tool ${VG}/vg_sigma.py with a CLI: --root <screen folder> (default ${PS}) --out <folder>. It MUST refuse (exit 2, nothing read) to touch any continuation of the root unless <root>/score/score.json exists with STATUS final and every queue entry decided; it reads the COUNTED list from score.json; it records the sha256 of itself, SPEC.txt, every input file and the PS tools it imports; deterministic output (score-like json + txt). Also a --pair mode for validation on an explicit pair path (any arm form) that does NOT need a screen root.
4. Unit tests (pytest, under ${VG}/tests): bucket assignment at the edges (k = 0, 49, 50, 149, 150, 199, 200, 249, 250, 999, 1000); G with bootstrap at truncation and none at termination on hand-built sequences with exact expected values; the unit normalisation; the refusal guard (on a synthetic root inside your folder: missing score.json, STATUS incomplete, an undecided entry); phase feeding equal to read_bs's for the same states; sigma extraction including any floor. ruff (E,F,W,B, line 120) clean.
5. Validations (nice 19, one at a time, small): (a) --pair on BS2's control_2501 final pair and one critic_blind final pair (record per-bucket V-G); (b) --pair on the PS start pair and on a PS/validate critic_phase pair (phase fed; the critic's phase columns are zero there so its values must equal the plain critic's: check that); (c) if feasible, reproduce one number from the why-probe on s42 with its own settings; (d) timing per episode and the estimated post-screen cost for 8 final pairs + S at N episodes.
6. Write ${VG}/NOTES.txt (what, how, every decision, validation results, open items) and ${VG}/SHA256SUMS.txt over SPEC.txt, vg_sigma.py and the tests. Delete your bulky temp files; report df -B1 /.
Return the structured result.`

const BUILD_SCHEMA = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['DONE', 'DONE_WITH_ISSUES', 'BLOCKED'] },
    summary: { type: 'string' },
    key_numbers: { type: 'string' },
    sha256: { type: 'string', description: 'sha256 of SPEC.txt, vg_sigma.py and each test file' },
    open_items: { type: 'array', items: { type: 'string' } },
  },
  required: ['status', 'summary', 'key_numbers', 'sha256', 'open_items'],
}

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    ready: { type: 'boolean', description: 'true if no blocking finding remains' },
    summary: { type: 'string' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          severity: { type: 'string', enum: ['blocking', 'minor', 'info'] },
          claim: { type: 'string' },
          evidence: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['id', 'severity', 'claim', 'evidence', 'fix'],
      },
    },
  },
  required: ['ready', 'summary', 'findings'],
}

const checkPrompt = (label, extra) => `You are an INDEPENDENT CHECKER (${label}) of a report-only measurement tool another agent built in ${VG} (SPEC.txt, vg_sigma.py, tests/, NOTES.txt). ${CONTEXT}
${RULES}
Your own folder: ${VG}/${label} (create it; write only there). Do not edit the builder's files.
Your job is to try to BREAK it, with your own code:
1. Re-implement V - G by bucket yourself (do NOT import vg_sigma.py; you may import PS's tools read only for loading pairs and building envs) and compare with the tool's --pair output on at least two pairs: one BS2 final pair (${S2}/r10round/bias_screen2/runs/...) and one PS/validate critic_phase pair, same seeds and episodes. Differences should be exact or float round-off; explain any other.
2. Check the semantics against SB3 and the training code: gamma, reward normalisation units (as the buffer's returns), truncation bootstrap at k = 1000 with V of the terminal observation, no bootstrap at termination, the k convention (k = _step_count at the observation; gate k >= 200), and that the phase is fed to the critic exactly as in training for critic_phase and not at all for control. Cross-check with the why-probe's method (${S2}/com_revisit/notes/phase_probe, verify_why).
3. Mutation tests on copies inside your folder (shift buckets by one step, drop the bootstrap, bootstrap terminations, use unnormalised rewards, feed the phase to control, skip the phase for critic_phase, wrong tail index): the tests or your comparison must catch each.
4. The refusal guard: on synthetic roots in your folder (never create anything in ${PS}), confirm it refuses without a final score.json and with any undecided entry, and that it reads only the COUNTED runs.
5. SPEC: seeds collision-free (re-run the check your own way), the stated statistics match the code, it says report only. Tail_3 / tail_2 indices verified against the action layout.
6. Outcome-blindness and rules: confirm from the builder's command log and the code that nothing touched ${PS}/runs, reads, score, tmp or continuation logs, and that nothing was written outside ${VG}; PS's pinned files unchanged (sha256 vs ${PS}/APPROVED).
${extra}
Return findings (blocking / minor / info), each with evidence and a concrete fix.`

phase('Build')
const build = await agent(BUILD, { label: 'vg:builder', phase: 'Build', schema: BUILD_SCHEMA })
if (!build) { return { error: 'builder returned nothing' } }
log('builder: ' + build.status)

phase('Check')
const check = await agent(checkPrompt('check1', ''), { label: 'vg:checker', phase: 'Check', schema: FINDINGS_SCHEMA })
if (!check) { return { build, error: 'checker returned nothing' } }
const actionable = check.findings.filter(f => f.severity !== 'info')
log(`checker: ready=${check.ready}, ${actionable.length} actionable of ${check.findings.length}`)

let fix = null, recheck = null
if (actionable.length > 0) {
  phase('Fix')
  fix = await agent(`You are the FIXER of a report-only measurement tool in ${VG}. ${CONTEXT}
${RULES}
Your folder for notes and temp: ${VG}/fixer (you MAY edit ${VG}/SPEC.txt, ${VG}/vg_sigma.py, ${VG}/tests/** and ${VG}/NOTES.txt; keep an orig/ copy of each file before editing).
The independent checker's findings (JSON): ${JSON.stringify(check.findings)}
For each finding: verify it against the sources first; fix what holds (minimal fix), say why for any you reject. Then re-run the unit tests, ruff, and the validations the fix touches (nice 19, small). Refresh ${VG}/SHA256SUMS.txt and write ${VG}/FIXES.txt. Return the structured result (status, summary, key_numbers incl. what changed, sha256 of SPEC.txt, vg_sigma.py and tests, open_items).`,
    { label: 'vg:fixer', phase: 'Fix', schema: BUILD_SCHEMA })
  const hadBlocking = check.findings.some(f => f.severity === 'blocking')
  if (fix && hadBlocking) {
    phase('Recheck')
    recheck = await agent(checkPrompt('check2', `This is a RE-CHECK after a fixer (read ${VG}/FIXES.txt and diff each changed file against ${VG}/fixer/orig). Confirm every blocking finding of the first check is fixed and nothing broke; re-run your own comparison on one pair. Earlier findings: ${JSON.stringify(check.findings.filter(f => f.severity === 'blocking'))}`),
      { label: 'vg:recheck', phase: 'Recheck', schema: FINDINGS_SCHEMA })
  }
}
return { build, check, fix, recheck }

